@contextlib.contextmanager
def temp_root():
    """把「库根」临时指向一个合成目录，**只在本进程内**改模块级变量。

    为什么要它：selftest 必须走真实的写盘路径（否则测的是另一个函数），
    但**绝对不能在真库上写**。做法是让 ROOT 在 selftest 期间整体指向 tempfile
    合成库——路径一字不改地跑，落点全在临时目录里。退出时无论成败都恢复。
    """
    old_root, old_cwd, old_env = ROOT, os.getcwd(), os.environ.get(QC_DIR_ENV)
    tmp = K.make_temp_dir(prefix="qc_link_twins_selftest_")
    try:
        globals()["ROOT"] = tmp
        os.chdir(tmp)
        # 缓存目录也一并指向合成库，否则"干跑写缓存"会落进真库 .qc/
        os.environ[QC_DIR_ENV] = os.path.join(tmp, ".qc")
        yield tmp
    finally:
        os.chdir(old_cwd)
        globals()["ROOT"] = old_root
        if old_env is None:
            os.environ.pop(QC_DIR_ENV, None)
        else:
            os.environ[QC_DIR_ENV] = old_env
        shutil.rmtree(tmp, ignore_errors=True)



def canon(s):
    """DOI/字符串归一：只留字母数字，便于跨写法比较。"""
    return re.sub(r"[^a-z0-9]", "", (s or "").lower())


def doi_from_md_name(name):
    """从提取件文件名恢复 DOI：`10_1002_adfm_202400001__标题` → `10.1002/adfm.202400001`。"""
    stem = os.path.splitext(os.path.basename(name))[0]
    parts = stem.split("__")[0].split("_")
    if len(parts) < 3 or parts[0] != "10":
        return None
    return "10.%s/%s" % (parts[1], ".".join(parts[2:]))


def build_lexicon():
    """返回 (stem_map, doi_map)。"""
    stem_map, doi_map = {}, {}
    for d in TEXT_DIRS + LEGACY_DIRS:
        for f in glob.glob(os.path.join(d, "**", "*.md"), recursive=True):
            stem_map.setdefault(os.path.splitext(os.path.basename(f))[0], f)
            doi = doi_from_md_name(f)
            if doi:
                doi_map.setdefault(canon(doi), f)
    return stem_map, doi_map


def pdf_doi(path):
    """从 PDF 元数据或前两页正文里恢复 DOI。失败返回 None。"""
    try:
        import fitz
    except Exception:
        return None
    try:
        d = fitz.open(path)
        md = d.metadata or {}
        blob = " ".join(str(md.get(k, "")) for k in ("subject", "keywords", "title"))
        for m in DOI_RE.findall(blob):
            return m.rstrip(".,;)")
        t = " ".join(d[i].get_text() for i in range(min(2, d.page_count)))
        d.close()
        for m in DOI_RE.findall(t):
            return m.rstrip(".,;)")
    except Exception:
        return None
    return None


def doi_cache_path():
    """DOI 缓存落点。

    🔴 为什么显式看 `MATSCI_QC_DIR`：缓存的**写出**只允许发生在 apply 路径上
    （见 `plan(write_cache=…)`）。selftest 需要把这条路径整体指到合成目录，
    否则"证明干跑无副作用"这件事就没法在真库上验证。
    """
    env = os.environ.get("MATSCI_QC_DIR")
    d = env if env else qc_work_dir(create=True)
    return os.path.join(d, "pdf_doi_cache.json")


def load_doi_cache():
    p = doi_cache_path()
    if os.path.exists(p):
        try:
            return json.load(open(p, encoding="utf-8"))
        except Exception:
            return {}
    return {}


def save_doi_cache(cache):
    p = doi_cache_path()
    os.makedirs(os.path.dirname(p), exist_ok=True)
    json.dump(cache, open(p, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    return p


def title_tokens(s):
    s = re.sub(r"^(10_\d{4,9})_(\w+)_(\w+)__", "", s)
    return {w for w in re.findall(r"[a-z0-9]+", s.lower())
            if len(w) > 3 and w not in STOP}


def is_pdf_binary(p):
    try:
        with open(p, "rb") as fh:
            return fh.read(5).startswith(b"%PDF")
    except Exception:
        return False


def readable(r):
    """该 raw 是否已是「可读文本证据」。"""
    if not os.path.exists(r):
        return False
    if r.lower().endswith(".pdf"):
        return not is_pdf_binary(r)
    try:
        return len(read_text(r)) > 20000
    except Exception:
        return False


def find_twin(pdf_rel, stem_map, doi_map, doi_cache, use_doi=True, write_cache=False):
    """为单个 PDF 找提取件。返回 (提取件路径 | None, 方法)。

    `write_cache` **只影响"要不要把缓存落盘"**，与是否算出 DOI 无关：
    🔴 干跑（write_cache=False）时缓存只留在内存里。旧实现在 `main()` 末尾
    **无条件** `save_doi_cache`，于是"干跑"会写 `.qc/pdf_doi_cache.json` ——
    干跑有写盘副作用，直接违反「默认干跑」这条纪律的**本意**
    （干跑的定义是"不改变仓库状态"，不是"不改变 wiki 页面"）。
    """
    stem = os.path.splitext(os.path.basename(pdf_rel))[0]
    # ① basename 同名（旧结构）
    if stem in stem_map:
        return stem_map[stem], "stem"
    if use_doi and doi_map:
        # ② DOI（元数据/正文）
        key = pdf_rel.replace(os.sep, "/")
        if key not in doi_cache:
            if not write_cache:
                return None, None      # 干跑：不落缓存，也不为此扫 PDF
            doi_cache[key] = pdf_doi(pdf_rel) or ""
        doi = doi_cache.get(key)
        if doi and canon(doi) in doi_map:
            return doi_map[canon(doi)], "doi"
    return None, None


def plan(stem_map, doi_map, doi_cache, use_doi=True, verbose=False, write_cache=False):
    """返回 (待补页清单, already, nopair, by_method)。**不写盘**。

    待补项为 `(文件, 原文本, sources 块匹配, 提取件路径)`，供 `apply_entry()` 改写；
    这样 `--apply` 路径能复用同一份计划，不在写盘阶段重算（计划与实际写盘必须同源）。
    """
    todo, already, nopair = [], 0, 0
    by_method = {}
    for f in sorted(glob.glob("wiki/sources/*.md")):
        t = read_text(f)
        head = t[: t.find("---", 3)]
        raws = re.findall(r"\[\[(raw/[^\]|]+)", head)
        if not raws:
            continue
        if any(readable(r) for r in raws):
            continue
        pdfs = [r for r in raws if r.endswith(".pdf")]
        if not pdfs:
            continue
        tw, how = None, None
        for p in pdfs:
            tw, how = find_twin(p, stem_map, doi_map, doi_cache, use_doi,
                                write_cache=write_cache)
            if tw:
                break
        if not tw:
            nopair += 1
            if verbose:
                print("  NO-TWIN:", os.path.basename(f)[:-3])
            continue
        by_method[how] = by_method.get(how, 0) + 1
        tw = tw.replace(os.sep, "/")
        if ("[[%s]]" % tw) in t:
            already += 1
            continue
        # 🔴 `sources:` 行块必须**停在闭合 `---` 之前**。
        #    旧正则写成 `((?:[ \t]*-[^\n]*\n)+)`：`sources:` 是该块最后一段时，
        #    匹配会一路吃到 `---\n`（`-` 开头的闭合围栏也满足 `[ \t]*-`），
        #    于是 `apply_entry` 把新条目插在闭合 `---` **之后** ——
        #    链接落到**正文**里、frontmatter 少了一条 sources ⇒ 该提取件
        #    永远不算"已补"（工具每次重跑都再报一次），且回链不在元数据里。
        #    这里显式用「不是闭合围栏」的判据收紧。
        m = re.search(r"^sources:\n((?:(?!(?:---|\.\.\.)\s*$)[ \t]*-[^\n]*\n)+)",
                      t, re.M)
        if not m:
            continue
        todo.append((f, t, m, tw))
    return todo, already, nopair, by_method


def apply_entry(f, t, m, tw):
    """把提取件入口追加进 sources 块；返回新全文。

    ⚠️ 这里**不手工拼 frontmatter**：改的是正文之前的 `sources:` 行块，
    全文原样保留 ⇒ 不存在"开/闭围栏缺换行"的拼接风险（124 页事故的形态）。
    但写盘前仍要用同一解析器复核 frontmatter 还能读出来（见 main 与 selftest 夹具）。
    """
    newblock = m.group(1).rstrip("\n") + "\n  - \"[[%s]]\"\n" % tw
    out = t[: m.start(1)] + newblock + t[m.end(1):]
    # 写前自证：插入的行必须**落在 frontmatter 之内**。否则该链接不会被摄入统计
    # 看到（回链在正文里），且工具每次重跑都会重复报同一页。
    from kb_lib import split_frontmatter as _sf
    if ("[[%s]]" % tw) not in _sf(out)[0]:
        raise ValueError("插入的提取件入口落在 frontmatter 之外（sources 行块匹配越界）")
    return out


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）+ 干跑无副作用/写盘隔离夹具。"""
    ok = True

    # 🔴 守卫：进入时对真实落点拍快照，退出前比对——证明自检没碰真实库
    guard = _guard_state(wiki_glob=True, extra_paths=(os.path.join(ROOT, ".qc"),))

    stem_map, doi_map = build_lexicon()
    # 提取件词表：空库（尚无 raw/text 提取件）时为 0 是合法状态，不作失败断言；
    # 词表构建与配对机制由下方合成库夹具钉住（原缺陷「词表恒为空」在夹具里必红）。
    print(f"  [info] 提取件词表 -> {len(stem_map)} stem / {len(doi_map)} DOI"
          "（空库为 0 属合法；机制见合成夹具）")
    # 正例：DOI 恢复可反算（这是两级配对里的关键一环）
    got = doi_from_md_name("10_1002_adfm_202400001__Some-Title.md")
    want = "10.1002/adfm.202400001"
    print(f"  [{'ok' if got == want else 'FAIL'}] DOI 反算 -> {got}")
    ok = ok and got == want
    # 反例：非 DOI 前缀的文件名不得凭空造出 DOI
    got = doi_from_md_name("Some-Ordinary-Name.md")
    print(f"  [{'ok' if got is None else 'FAIL'}] 反例 无 DOI 前缀 -> None")
    ok = ok and got is None
    # 正例：DOI canon 对不同写法等价，且不与无关串相等
    same = canon("10.1002/adfm.202400001") == canon("10_1002_adfm_202400001")
    print(f"  [{'ok' if same else 'FAIL'}] canon 等价性（点/下划线写法）")
    ok = ok and same
    # 反例：绝不存在的 DOI 不得命中词表
    print(f"  [{'ok' if canon('10.9999/nope') not in doi_map else 'FAIL'}] "
          f"反例 不存在的 DOI 未命中")
    ok = ok and canon("10.9999/nope") not in doi_map
    # 正例：plan() 可跑通且不改盘
    doi_cache = load_doi_cache()
    todo, already, nopair, by = plan(stem_map, doi_map, doi_cache,
                                     use_doi=False, verbose=False)
    print(f"  [info] plan(use_doi=False) -> 待补 {len(todo)} | 已有 {already} | "
          f"无孪生 {nopair} | 按方法 {by}")
    # 正例：配对机制必须**至少有一级真正可用**，否则工具结构上不可能命中。
    #
    # ⚠️ 2026-10-05 修正本断言：初版写成「stem_map 非空 **且** doi_map 非空」，
    #    把「DOI 索引非空」当成了不变量。但 DOI 层只是 ① 的**兜底**——
    #    当提取件已改为标题名（与 raw/pdf 同源）时，`doi_map` 自然为空，
    #    而 ① basename 同名 反而成为主力（实测 stem 交集非空）。
    #    ⇒ 正确的不变量是「**有可配对的证据**」，不是「某一级非空」。
    #    这正是历史自检事故的同型错误：把「某一种实现」当成「规范」。
    def _pairing_power():
        """本库当前能提供的配对能力：(方法名, 可命中的候选页数)。"""
        powers = {}
        if doi_map:
            powers['doi'] = len(doi_map)
        # ① 同名：数一数有多少 source 页引用的 pdf 能在 stem_map 里命中
        hit = 0
        for f in sorted(glob.glob("wiki/sources/*.md")):
            t = read_text(f)
            head = t[: t.find("---", 3)]
            for r in re.findall(r"\[\[(raw/[^\]|]+\.pdf)", head):
                st = os.path.splitext(os.path.basename(r))[0]
                if st in stem_map:
                    hit += 1
                    break
        if hit:
            powers['stem'] = hit
        return powers

    powers = _pairing_power()
    if glob.glob("wiki/sources/*.md"):
        usable = bool(powers)
        print(f"  [{'ok' if usable else 'FAIL'}] 配对机制可用 -> {powers or '无任何可用层级'}")
        ok = ok and usable
    else:
        print("  [skip] 库内尚无 source 页，配对能力不作断言（机制见合成夹具）")
    # 反例：绝不存在的 stem 不得被对上（防止「什么都能配」的虚高）
    miss = stem_map.get("绝不存在的-stem-xyz")
    print(f"  [{'ok' if miss is None else 'FAIL'}] 反例 不存在的 stem 不命中")
    ok = ok and miss is None

    # ---- 夹具（只对合成库，绝不碰真库）----
    try:
        from kb_lib import split_frontmatter as _sf
        with temp_root() as tmp:
            td = os.path.join(tmp, "raw", "text")
            sd = os.path.join(tmp, "wiki", "sources")
            os.makedirs(td, exist_ok=True)
            os.makedirs(sd, exist_ok=True)
            tw_rel = os.path.join("raw", "text", "Twin-Title.md")
            with open(tw_rel, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("# 提取件\n" + "正文" * 200)
            p_src = os.path.join(sd, "S-待补.md")
            with open(p_src, "w", encoding="utf-8", newline="\n") as fh:
                fh.write('---\ntype: source\nsources:\n  - "[[raw/pdf/Twin-Title.pdf]]"\n'
                         "---\n\n# 来源页\n正文\n")
            stem_map2, doi_map2 = build_lexicon()

            # 夹具 1（正例）：合成库里能规划出 1 条待补
            todo2, _a2, _n2, _b2 = plan(stem_map2, doi_map2, {}, use_doi=False)
            c1 = len(todo2) == 1 and todo2[0][3].replace(os.sep, "/").endswith(
                "raw/text/Twin-Title.md")
            print(f"  [{'ok' if c1 else 'FAIL'}] 夹具 正例 合成库规划出待补 -> {len(todo2)} 条")
            ok = ok and c1

            # 🔴 夹具 2：干跑分支**零写盘副作用**（缓存不得落盘）
            cache_file = doi_cache_path()
            before_exists = os.path.exists(cache_file)
            _t3, _a3, _n3, _b3 = plan(stem_map2, doi_map2, {}, use_doi=True,
                                      write_cache=False)
            c2 = (not before_exists and not os.path.exists(cache_file))
            print(f"  [{'ok' if c2 else 'FAIL'}] 🔴 夹具 干跑无副作用：DOI 缓存未落盘 -> "
                  f"{cache_file}")
            ok = ok and c2

            # 夹具 3（🔴 frontmatter 不丢）：走真实写盘路径：备份 → 写 → 写后复算
            saved = backup_files([x[0] for x in todo2])
            written = []
            for f, t, m, tw in todo2:
                t2 = apply_entry(f, t, m, tw)
                if not _sf(t2)[0].strip():
                    continue
                write_keep_eol(f, t2)
                written.append(f)
            fm, body = _sf(read_text(p_src))
            c3 = ([os.path.abspath(x) for x in written] == [os.path.abspath(p_src)]
                  and len(saved) == 1 and "[[raw/text/Twin-Title.md]]" in fm
                  and body.lstrip().startswith("# 来源页"))
            print(f"  [{'ok' if c3 else 'FAIL'}] 🔴 夹具 frontmatter 不丢：写后回链已补且 "
                  f"frontmatter 可解析（备份 {len(saved)} / 写 {len(written)}）")
            ok = ok and c3

            # 反例：写后复算必须抓出"写了但 frontmatter 读不出"的页
            p_broken = os.path.join(sd, "B-写坏了.md")
            with open(p_broken, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("---\ntype: source\n---# 标题\n")
            caught = False
            sys.stdout.flush()          # 让下面 stderr 的告警落在夹具判定之后，输出不串行
            try:
                verify_written([p_src, p_broken])
            except SystemExit as e:
                caught = (e.code or 0) != 0
            print(f"  [{'ok' if caught else 'FAIL'}] 反例 写后复算抓出 frontmatter 丢失"
                  f"（并置非零退出）")
            ok = ok and caught

            # 夹具 4（正例）：apply 路径**应当**能落缓存（证明缓存只是"挪到 apply"，
            # 不是被一删了之 —— 否则等于把功能删掉换一个绿的自检）
            c4 = True
            try:
                _t4, _a4, _n4, _b4 = plan(stem_map2, doi_map2, {}, use_doi=True,
                                          write_cache=True)
                cp = save_doi_cache({})
                c4 = bool(cp) and os.path.exists(cp)
            except Exception:                                     # noqa: BLE001
                c4 = False
            print(f"  [{'ok' if c4 else 'FAIL'}] 正例 apply 路径可落 DOI 缓存"
                  f"（干跑路径未把它废掉）")
            ok = ok and c4
    except Exception as e:                                        # noqa: BLE001
        print(f"  [FAIL] 夹具异常: {type(e).__name__}: {e}")
        ok = False

    # 🔴 守卫：自检未改动仓库内任何落点
    diff = _guard_diff(guard, _guard_state(
        wiki_glob=True, extra_paths=(os.path.join(ROOT, ".qc"),)))
    print(f"  [{'ok' if not diff else 'FAIL'}] 🔴 守卫：自检未改动仓库内任何落点"
          f"（{len(diff)} 处变化）")
    if diff:
        for d in diff[:10]:
            print("       ", d)
    ok = ok and not diff

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="为 source 页补入提取件入口")
    ap.add_argument("--apply", action="store_true", help="真正写盘（默认干跑）")
    ap.add_argument("--no-doi", action="store_true",
                    help="跳过 DOI 扫描（快，召回低）")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()
    if a.selftest:
        return selftest()

    stem_map, doi_map = build_lexicon()
    doi_cache = load_doi_cache()
    # 🔴 `write_cache=a.apply`：**干跑一律不落缓存**（旧实现在末尾无条件保存，
    #    干跑会写 `.qc/pdf_doi_cache.json` ＝ 干跑有写盘副作用）。
    todo, already, nopair, by = plan(stem_map, doi_map, doi_cache,
                                     use_doi=not a.no_doi, verbose=not a.apply,
                                     write_cache=a.apply)

    if not a.apply:
        for f, t, m, tw in todo:
            print("  待补: %-50s + [[%s]]" % (os.path.basename(f)[:-3], tw))
        print("%s: 补入提取件入口 %d 页 | 已有 %d | 无孪生件 %d | 配对方法 %s"
              % ("DRY-RUN", len(todo), already, nopair, by))
        if todo:
            print("加 --apply 执行写盘（DOI 缓存也只在 --apply 时写）")
        return 0

    # —— 铁律 3：批量写盘前先备份、写后复算总量 ——
    saved = backup_files([x[0] for x in todo])
    if todo and not saved:
        print("❌ 备份失败，拒绝写盘", file=sys.stderr)
        return 2
    if saved:
        print("备份 %d 个待改文件 -> %s" % (len(saved), backup_dir()))

    from kb_lib import split_frontmatter
    written = []
    for f, t, m, tw in todo:
        t2 = apply_entry(f, t, m, tw)
        # 写前复核：必须仍能被同一解析器读出 frontmatter
        if not split_frontmatter(t2)[0].strip():
            print("  [skip] 写前复核失败（未写盘）:", os.path.basename(f))
            continue
        write_keep_eol(f, t2)
        written.append(f)

    if not a.no_doi:
        cp = save_doi_cache(doi_cache)      # 只在这一条（apply）路径上落盘
        print("DOI 缓存 -> %s" % cp)

    print("%s: 补入提取件入口 %d 页 | 已有 %d | 无孪生件 %d | 配对方法 %s"
          % ("APPLIED", len(written), already, nopair, by))
    verify_written(written)
    return 0


if __name__ == "__main__":
    sys.exit(main())
